<section class="admin-v2-table-panel"><div class="admin-v2-panel-head"><h3>السجلات (<?=e($total)?>)</h3><span>صفحة <?=e($page)?> من <?=e($pages)?></span></div><div class="admin-v2-table-wrap"><table class="admin-v2-table"><thead><tr><th>الوقت</th><th>المنفذ</th><th>الإجراء</th><th>الهدف</th><th>التفاصيل</th><th>العنوان</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="admin-v2-empty">لا توجد سجلات مطابقة.</div></td></tr><?php else: foreach($rows as $row):?><tr><td data-label="الوقت"><small><?=e((string)$row['created_at'])?></small></td><td data-label="المنفذ"><strong><?=e((string)($row['admin_name']??'نظام'))?></strong><small><?=e((string)($row['username']??''))?></small></td><td data-label="الإجراء"><code><?=e((string)$row['action'])?></code></td><td data-label="الهدف"><?=e((string)($row['target_type']??'—'))?> #<?=e((string)($row['target_id']??'—'))?></td><td data-label="التفاصيل"><?=e((string)($row['details']??'—'))?></td><td data-label="العنوان"><small><?=e((string)($row['ip_address']??'—'))?></small></td></tr><?php endforeach; endif;?></tbody></table></div><?php if($pages>1):?><nav class="admin-v2-pagination" aria-label="ترقيم سجل الإجراءات"><?php for($i=1;$i<=$pages;$i++):?><a class="admin-v2-small-button <?=$i===$page?'good':''?>" href="/admin-v2/audit?page=<?=$i?>&q=<?=urlencode($q)?>"><?=$i?></a><?php endfor;?></nav><?php endif;?></section>
